def expandPolynomial(expr):
    MOD = 10 ** 9 + 7
    prec = {'+': 1, '-': 1, '*': 2}
    vals = []
    ops = []

    def apply():
        op = ops.pop()
        b = vals.pop()
        a = vals.pop()
        if op == '*':
            res = [0] * (len(a) + len(b) - 1)
            for i, x in enumerate(a):
                if x:
                    for j, y in enumerate(b):
                        res[i + j] = (res[i + j] + x * y) % MOD
        else:
            sign = 1 if op == '+' else -1
            res = [0] * max(len(a), len(b))
            for i, x in enumerate(a):
                res[i] = x
            for i, y in enumerate(b):
                res[i] = (res[i] + sign * y) % MOD
        vals.append(res)

    i = 0
    n = len(expr)
    expect_operand = True
    while i < n:
        c = expr[i]
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            vals.append([int(expr[i:j]) % MOD])
            i = j
            expect_operand = False
            continue
        if c == 'x':
            vals.append([0, 1])
            expect_operand = False
        elif c == '(':
            ops.append(c)
            expect_operand = True
        elif c == ')':
            while ops[-1] != '(':
                apply()
            ops.pop()
            expect_operand = False
        else:
            if expect_operand:      # unary minus: 0 - term
                vals.append([0])
            while ops and ops[-1] != '(' and prec[ops[-1]] >= prec[c]:
                apply()
            ops.append(c)
            expect_operand = True
        i += 1
    while ops:
        apply()
    res = vals[0]
    while len(res) > 1 and res[-1] == 0:
        res.pop()
    return res
